import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"ADR-0007: Sovereign Console Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"sovereign-os/adrs/0007-console-authentication.md","filePath":"sovereign-os/adrs/0007-console-authentication.md"}'),s={name:"sovereign-os/adrs/0007-console-authentication.md"};function n(r,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0007-sovereign-console-authentication" tabindex="-1">ADR-0007: Sovereign Console Authentication <a class="header-anchor" href="#adr-0007-sovereign-console-authentication" aria-label="Permalink to &quot;ADR-0007: Sovereign Console Authentication&quot;">​</a></h1><p><strong>Status:</strong> Accepted <strong>Date:</strong> 2026-07-31 <strong>Decision owner:</strong> Project creator <strong>Related ADR:</strong> <a href="./0005-sovereign-console-and-health-boundary.html">ADR-0005</a><strong>Related RFCs:</strong> <a href="./../rfcs/0014-appliance-update-system.html">RFC-0014</a>, <a href="./../rfcs/0015-update-discovery.html">RFC-0015</a><strong>Related milestone:</strong> <a href="./../../ROADMAP.html">Update Discovery and Console Controls</a><strong>Supersedes:</strong> None</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./0005-sovereign-console-and-health-boundary.html">ADR-0005</a> deliberately shipped Console as <strong>read-only and unauthenticated</strong> on the trusted LAN, and said so explicitly:</p><blockquote><p>Authentication is required before settings, restarts, updates, credential changes, detailed logs, or other state-changing operations are added.</p></blockquote><p>That boundary has held. The initial Console slice — <code>/console/</code>, <code>/console/health/</code>, <code>/api/v1/health</code> — exposes only bounded, non-sensitive health data (version, uptime, aggregate memory/storage, temperature, interface names/addresses, named service health) from an unprivileged, loopback-only, systemd-hardened health process, per <a href="./../design/console-health.html">docs/design/console-health.md</a>. No credential exists to check because nothing on that surface can change device state.</p><p>That is no longer true of what&#39;s queued up next. RFC-0015 (Update Discovery) was scoped explicitly to avoid this problem for its own device-side <code>check</code> subcommand, and says so in its own Summary:</p><blockquote><p>This RFC proposes the mechanism for that check... and explicitly does not propose a Console UI or an automatic install path. Both remain out of scope until Console has an authentication story (see ADR-0005), per the project owner&#39;s own prior decision on that boundary.</p></blockquote><p>ROADMAP milestone &quot;Update Discovery and Console Controls&quot; lists, as still-planned work blocked on this: showing update details in Console, <strong>user-triggered download and installation</strong>, and reporting download/verification/staging/activation/validation/rollback states. All of that means Console needs to be able to invoke <code>sovereign-update prepare/backup/stage/activate/restore/prune/rotate-trust</code> — every one of which is currently an operator-run, SSH-gated command — from a LAN-facing, currently-unauthenticated web page. The same question will eventually apply to any future Pi-hole admin actions Console might surface directly rather than linking out to <code>/dns/admin/</code>.</p><p>This ADR does not choose Console&#39;s authentication mechanism for the project owner. It lays out the realistic options at this project&#39;s current scale (a small/solo maintainer, self-hosted household appliance, budget-conscious, values self-sufficiency over third-party dependencies) so a deliberate choice can be recorded and revisited as Console&#39;s privileged surface grows, the same way ADR-0006 did for production signing-key custody.</p><h3 id="what-this-actually-protects" tabindex="-1">What this actually protects <a class="header-anchor" href="#what-this-actually-protects" aria-label="Permalink to &quot;What this actually protects&quot;">​</a></h3><p>Once Console gains any mutating capability, whoever can reach it over the LAN (and, if the device is ever exposed beyond the LAN — see Threat Model below — anyone who can reach it at all) can:</p><ul><li>trigger an appliance update install, restore a backup, or rotate the update trust store on a device that answers DNS for the household;</li><li>potentially change Pi-hole configuration or credentials, if Console ever grows admin actions beyond linking to <code>/dns/admin/</code>;</li><li>at minimum, cause disruption (unwanted reboots, restores, or update installs) even without extracting any secret.</li></ul><p>This is not about protecting a secret value the way ADR-0006&#39;s signing key is — health data and Console&#39;s own state aren&#39;t confidential in the same sense. It&#39;s about gating <strong>who is allowed to cause state change</strong> on a device with real household impact (DNS for every device on the network, Pi-hole credentials, the update trust chain). The existing layered defenses (signed manifests, staged/health-gated activation, automatic rollback) constrain what a <em>bad update</em> can do once triggered; they do nothing to constrain <em>who is allowed to trigger one</em> — that is what Console authentication is for.</p><h3 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h3><p>Sovereign OS&#39;s stated deployment model is a self-hosted household appliance on a trusted LAN, not exposed to the public internet by default (see <a href="./../operations/first-login-and-network-setup.html">docs/operations/first-login-and-network-setup.md</a>: &quot;Do not expose the preview appliance directly to the internet&quot;). Realistic threats at this scale, roughly in order of likelihood:</p><ul><li><strong>Other devices/users on the same LAN</strong>, not fully trusted: guests, IoT devices with their own compromises, a household member who shouldn&#39;t have admin access, a compromised laptop already on the network. This is the primary threat this ADR needs to address — Console living on the LAN doesn&#39;t mean everyone reachable on the LAN should be able to trigger updates or restores.</li><li><strong>A LAN-adjacent attacker via a compromised browser session</strong> (e.g. a malicious web page open in the same browser as an authenticated Console session performing a request against <code>sovereign.local</code> — CSRF-shaped), independent of whatever auth mechanism is chosen.</li><li><strong>Brute-force or credential-stuffing</strong> against whatever credential is chosen, if the device is ever port-forwarded or otherwise made reachable from outside the LAN despite guidance not to (operators do this in practice more often than documentation assumes).</li><li><strong>Remote unauthenticated exploitation</strong> of Console itself (a vulnerability in the auth mechanism or the app) — the highest-severity but hopefully lowest-likelihood case, and the main argument for keeping the mechanism as simple and well-trodden as possible rather than a bespoke scheme.</li></ul><p>This is a materially different threat model than ADR-0006&#39;s signing key (which must resist a targeted, motivated attacker seeking to compromise <em>every</em> device trusting that key). Console auth mainly needs to resist casual/opportunistic access from other LAN parties and defend in depth against the LAN boundary itself failing, not a nation-state adversary. That should shape session length, brute-force protection, and mechanism complexity toward &quot;solid and standard,&quot; not maximal.</p><h3 id="constraints-already-fixed-by-the-existing-design" tabindex="-1">Constraints already fixed by the existing design <a class="header-anchor" href="#constraints-already-fixed-by-the-existing-design" aria-label="Permalink to &quot;Constraints already fixed by the existing design&quot;">​</a></h3><ul><li>Nginx is the only LAN-facing HTTP service (ADR-0005); any auth mechanism is enforced there or in whatever Console backend Nginx proxies to, not scattered across services.</li><li>The health API backend is intentionally unprivileged and loopback-only. Any mutating Console backend that calls into <code>sovereign-update</code> needs at minimum a way to invoke a privileged action from an unprivileged web request — the auth mechanism and that privilege boundary are related but distinct problems; this ADR addresses who&#39;s allowed to ask, not how the ask reaches root.</li><li>An OS-level admin account (<code>sovereign</code>) already exists with SSH access and a mandatory first-login password-change flow (see <a href="./../operations/first-login-and-network-setup.html">docs/operations/first-login-and-network-setup.md</a>). It is the only credential concept that exists on the device today.</li><li>The Pi-hole admin password is already a <strong>separate</strong> credential from the Linux account password, by deliberate existing design (same document, section 3: &quot;The Linux login password and Pi-hole password remain separate&quot;). Any new Console credential adds a third, unless it&#39;s explicitly tied to one of the first two.</li><li>No web session, cookie, or login-form infrastructure exists anywhere in the appliance today — this would be new surface however it&#39;s built.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The project owner accepted the Initial Recommendation below: <strong>Option B (separate Console-specific credential) delivered as Option C (session-based login)</strong>, with Option D (mTLS) left open as a future defense-in-depth layer rather than a starting requirement.</p><p>Implemented as:</p><ul><li>A distinct credential, <code>pbkdf2_sha256</code>-hashed (600,000 iterations, stdlib <code>hashlib.pbkdf2_hmac</code>, no external dependency) at <code>/data/sovereign/console/admin-password.hash</code>, set via a new <code>sovereign-console-password</code> command mirroring <code>sovereign-pihole-password</code>&#39;s interactive, minimum-12-character, atomic-replace pattern.</li><li>A new loopback-only, systemd-hardened backend, <code>console-auth</code> (<code>sovereign-console-auth.service</code>, port 8091), proxied by Nginx at <code>/api/v1/auth/login</code>, <code>/api/v1/auth/logout</code>, and <code>/api/v1/auth/session</code> — the same shape as the existing <code>console-health</code> service.</li><li>Session-based login: an <code>HttpOnly</code>, <code>SameSite=Strict</code> cookie (no <code>Secure</code> attribute, since Nginx has no TLS listener to protect against — see the service&#39;s own comment on this), an 8-hour default session lifetime, and a CSRF token returned at login and required via <code>X-CSRF-Token</code> on mutating requests (currently just <code>logout</code>).</li><li>Rate limiting without lockout, per the Session Length and Brute-Force Considerations above: 5 failed attempts per source IP within 5 minutes triggers an increasing <code>Retry-After</code> delay rather than blocking the legitimate owner out.</li><li>A dedicated <code>sovereign-console</code> system group (declared via <code>systemd-sysusers.d</code>) grants the auth service&#39;s <code>DynamicUser</code> read access to the credential file without widening the existing, separately-owned <code>/data/sovereign/secrets/</code> directory Pi-hole&#39;s own credential lives under.</li></ul><p>A Console sign-in UI (login form, session restore on page load, sign-out) now calls this backend from the topbar, always through same-origin <code>fetch</code> with <code>preventDefault()</code>, respecting the page&#39;s <code>form-action &#39;none&#39;</code> CSP.</p><p>Hardware-qualified on Raspberry Pi 5: the full login/session/CSRF/logout/ rate-limiting flow, and the interactive <code>sovereign-console-password</code> script under a real pty, both verified against the real deployed service behind the real Nginx proxy, with the device fully reverted to its exact prior state (all four modified files restored byte-identical from the real <code>v0.1.0-preview.17</code> release bundle) afterward — see the <a href="./../research/console-authentication-hardware-qualification-report.html">hardware qualification report</a>.</p><p><strong>Explicitly not yet done, and deliberately out of this pass&#39;s scope</strong> per this ADR&#39;s own boundary (&quot;this ADR addresses who&#39;s allowed to ask, not how the ask reaches root&quot;):</p><ul><li>No mutating action exists yet for this auth layer to gate — Console remains read-only in practice until the &quot;Update Discovery and Console Controls&quot; milestone wires an actual <code>sovereign-update</code> action behind it, which needs its own follow-up design work for the privilege-escalation path from this unprivileged backend to a root update action.</li><li>A real signed-release install attempt (<code>v0.1.0-preview.18</code>) initially hit a structural gap unrelated to Console auth specifically — see <a href="./../research/appliance-file-set-update-ceiling-finding.html">the finding</a> — since fixed and hardware-qualified: <code>.18</code> is now genuinely installed via a real update, <code>console-auth</code>&#39;s binary included, confirmed persistent across a reboot. It still cannot actually <strong>run</strong> without a reflash: the systemd unit, <code>sysusers.d</code> group, and directory bootstrap it needs are base-image content no update delivers, confirmed by <code>sovereign-console-auth.service</code> not existing on the device after this install.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><h3 id="option-a-—-reuse-the-os-level-sovereign-account-credential" tabindex="-1">Option A — Reuse the OS-level <code>sovereign</code> account credential <a class="header-anchor" href="#option-a-—-reuse-the-os-level-sovereign-account-credential" aria-label="Permalink to &quot;Option A — Reuse the OS-level `sovereign` account credential&quot;">​</a></h3><p>Console prompts for the Linux account username/password (validated via PAM or an equivalent local check) and issues a session cookie on success.</p><ul><li><strong>No new credential to create, remember, or leak</strong> — one password to compromise a device&#39;s DNS and its update system, whether over SSH or Console.</li><li>Matches the mental model the first-login flow already establishes: &quot;the <code>sovereign</code> account is the device.&quot;</li><li><strong>Downsides:</strong> couples two different trust boundaries (remote shell access and web-triggered update/restore actions) to a single secret. A password chosen for SSH convenience becomes the same password gating destructive update actions from a browser, and vice versa. If Console&#39;s web auth is ever compromised through a mechanism-specific bug, SSH access is compromised too. Also needs a real mechanism to check a Linux password from an unprivileged web backend (PAM binding, or shelling to a small privileged helper) — nontrivial new attack surface of its own.</li></ul><h3 id="option-b-—-separate-console-specific-credential" tabindex="-1">Option B — Separate Console-specific credential <a class="header-anchor" href="#option-b-—-separate-console-specific-credential" aria-label="Permalink to &quot;Option B — Separate Console-specific credential&quot;">​</a></h3><p>A distinct username/password (or passphrase-only) pair, set on first use of any mutating Console action, stored as its own hashed secret (e.g. <code>/data/sovereign/secrets/console-admin-password</code>, mirroring how the Pi-hole password is already stored separately from the Linux one).</p><ul><li>Keeps the three trust boundaries (SSH, Pi-hole, Console) cleanly separated, matching the precedent the Pi-hole password already set.</li><li>Compromise of one credential doesn&#39;t hand over the others.</li><li><strong>Downsides:</strong> a third credential for the household to manage and not lose; needs its own first-set/reset flow analogous to first-login and the Pi-hole password script; if forgotten, needs its own recovery path (SSH in and reset it, similar to <code>sovereign-pihole-password</code>).</li></ul><h3 id="option-c-—-session-based-login-cookie-server-side-session-state" tabindex="-1">Option C — Session-based login (cookie + server-side session state) <a class="header-anchor" href="#option-c-—-session-based-login-cookie-server-side-session-state" aria-label="Permalink to &quot;Option C — Session-based login (cookie + server-side session state)&quot;">​</a></h3><p>Either credential model above, but formalized as a real login: a login form, a signed/opaque session cookie with an expiry, server-side (or signed-stateless) session validation on every mutating request, and logout.</p><ul><li>The standard, well-understood web pattern; easiest for a solo maintainer to implement correctly using existing libraries rather than inventing something bespoke.</li><li>Naturally supports session expiry (defense-in-depth against a left-open browser tab) and CSRF-token pairing to address the CSRF-shaped risk noted in Threat Model above.</li><li><strong>Downsides:</strong> is a login <em>system</em>, not just a check — needs secure cookie flags, CSRF protection, session storage/expiry, and rate-limiting on the login endpoint itself to resist brute-force. More to build and more to get subtly wrong than a stateless check, though this is well-worn ground with existing patterns to copy correctly rather than invent.</li></ul><h3 id="option-d-—-mtls-client-certificate" tabindex="-1">Option D — mTLS / client certificate <a class="header-anchor" href="#option-d-—-mtls-client-certificate" aria-label="Permalink to &quot;Option D — mTLS / client certificate&quot;">​</a></h3><p>Console requires a client certificate issued by a device-local CA; only browsers/devices provisioned with that certificate can reach mutating endpoints (or Console at all).</p><ul><li><strong>Strong protection against casual/opportunistic LAN access</strong> — a device without the certificate can&#39;t even open a login prompt to attack.</li><li>No password to phish, brute-force, or forget.</li><li><strong>Downsides:</strong> by far the most operationally heavy option for a household user: generating, installing, and trusting a client certificate in a browser is not something most non-technical users have ever done, and there&#39;s no existing UX precedent in this project for it. Needs a local CA the device stands up and manages (its own smaller version of the ADR-0006 key-custody problem). Losing the certificate (a wiped phone, a reinstalled browser) means a new SSH-gated re-provisioning step just to view Console again, which is a heavy cost for what today is <em>read-only</em> health browsing on devices that haven&#39;t needed any credential at all. Best suited as a defense-in-depth layer once Console has other auth, not as the sole mechanism, given the household-usability bar this project has held elsewhere (e.g. Wi-Fi setup and first login are both designed to be copy-pasteable from a terminal, not requiring cert tooling).</li></ul><h3 id="option-e-—-http-basic-auth-at-the-nginx-layer" tabindex="-1">Option E — HTTP Basic Auth at the Nginx layer <a class="header-anchor" href="#option-e-—-http-basic-auth-at-the-nginx-layer" aria-label="Permalink to &quot;Option E — HTTP Basic Auth at the Nginx layer&quot;">​</a></h3><p>Nginx enforces <code>auth_basic</code> with an <code>htpasswd</code>-style file in front of mutating routes (or all of <code>/console/</code>), no application-level session code at all.</p><ul><li>Minimal new code — Nginx already terminates every LAN request (ADR-0005) and already has this module built in.</li><li>Simplest possible mechanism to reason about and audit.</li><li><strong>Downsides:</strong> no real session concept (browsers cache Basic Auth credentials per-origin until closed, with inconsistent &quot;logout&quot; UX across browsers), no built-in brute-force throttling without additional Nginx config (<code>limit_req</code>), and it trains users to type a password into a plain, un-styled browser prompt rather than a page that&#39;s clearly part of the product — a worse fit for a project that has otherwise built a deliberate, calm Console UI (see <a href="./../design/console-health.html">docs/design/console-health.md</a>).</li></ul><h2 id="initial-recommendation" tabindex="-1">Initial Recommendation <a class="header-anchor" href="#initial-recommendation" aria-label="Permalink to &quot;Initial Recommendation&quot;">​</a></h2><p>Leaning toward <strong>Option B (separate Console-specific credential) delivered as Option C (proper session-based login)</strong> as the best fit for this project&#39;s scale and existing precedent, with Option D (mTLS) worth revisiting later as an optional defense-in-depth layer rather than the starting mechanism:</p><ul><li>Option B keeps faith with a pattern the project has already chosen once (Pi-hole&#39;s password is deliberately separate from the Linux one) rather than introducing the first place where a single credential spans both shell and web access. A Console-triggered <code>restore</code> or <code>rotate-trust</code> going wrong is a different blast radius than an SSH session, and they arguably deserve independent credentials the same reasoning already gave Pi-hole.</li><li>Option C is recommended over Option E specifically because Console&#39;s mutating actions (update install, restore, trust rotation) are meaningfully higher-consequence than &quot;view an admin dashboard,&quot; and this project has already invested in Console being a deliberate, calm product surface rather than infrastructure plumbing (ADR-0005&#39;s own rejected alternatives explicitly ruled out a container-management-style dashboard) — a real login page fits that better than a browser-native Basic Auth prompt, and session expiry plus CSRF protection are worth the modest extra implementation cost given what a successful CSRF-shaped request could trigger.</li><li>Option A is not recommended as the primary mechanism because it collapses two independently-useful trust boundaries (remote shell, web-triggered mutation) into one secret, for a marginal convenience gain (one password to remember instead of two) that this project has already decided against once for Pi-hole.</li><li>Option D is not recommended as the <em>starting</em> mechanism given the household-usability bar evident elsewhere in this project&#39;s own documentation (first login and Wi-Fi setup are both designed to be copy-paste simple), but is worth a later look once Console&#39;s privileged surface is large enough to justify the setup cost, especially if the device is ever expected to be reachable beyond the LAN.</li></ul><p>This recommendation is offered for the project owner&#39;s judgment, not as a default to implement without review.</p><h2 id="session-length-and-brute-force-considerations" tabindex="-1">Session Length and Brute-Force Considerations <a class="header-anchor" href="#session-length-and-brute-force-considerations" aria-label="Permalink to &quot;Session Length and Brute-Force Considerations&quot;">​</a></h2><p>Whichever option is chosen, given the LAN-primary threat model above:</p><ul><li>A moderate session length (hours, not minutes, and not &quot;forever&quot;) is reasonable for a trusted-household-LAN default — this is not a banking app — but sessions should still expire, and any mutating action (<code>activate</code>, <code>restore</code>, <code>rotate-trust</code>) is a reasonable point to require fresh confirmation regardless of session freshness, mirroring how <code>rotate-trust</code>&#39;s own lockout check already refuses actions that would leave a device unable to trust future updates (ADR-0006&#39;s Rotation section) — Console&#39;s auth layer should have an equivalent &quot;don&#39;t let one mistake brick the device&quot; instinct.</li><li>Basic rate-limiting on the login endpoint (Nginx <code>limit_req</code> or equivalent) is worth doing regardless of mechanism — it&#39;s cheap defense against both a compromised LAN device and the &quot;someone port-forwards this against documented guidance&quot; case.</li><li>No lockout-after-N-failures policy is recommended by default, to avoid a denial-of-service where a malicious LAN device locks the legitimate owner out of their own appliance; rate-limiting (slowing attempts) is preferred over lockout (blocking the owner) at this threat level.</li></ul><h2 id="credential-reset-recovery-considerations" tabindex="-1">Credential Reset / Recovery Considerations <a class="header-anchor" href="#credential-reset-recovery-considerations" aria-label="Permalink to &quot;Credential Reset / Recovery Considerations&quot;">​</a></h2><p>Analogous to Rotation/Revocation in ADR-0006, but for a login credential rather than a signing key:</p><ul><li>Whatever credential is chosen needs an SSH-gated reset path from the existing <code>sovereign</code> account, mirroring <code>sovereign-pihole-password</code> — losing the Console credential should never require a reflash the way losing the <em>only</em> trusted update-signing key would (ADR-0006&#39;s Recovery section).</li><li>If Option A is chosen instead of the recommendation above, resetting the Linux password already resets Console access as a side effect — worth flagging as exactly the coupling this ADR recommends against.</li><li>A compromised Console credential (e.g. a household member&#39;s laptop with a saved session gets compromised) should be recoverable by invalidating all existing sessions on password change, the same way changing a website password today typically signs out other devices.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li>Unblocks the &quot;Update Discovery and Console Controls&quot; milestone&#39;s Console-facing bullets (RFC-0015&#39;s explicitly deferred UI and installation-triggering scope) and any future Console-surfaced Pi-hole admin actions.</li><li>Gives Console a deliberate, documented auth boundary instead of an implicit &quot;we&#39;ll figure it out later&quot; gap, matching how ADR-0006 closed the equivalent gap for signing-key custody.</li><li>Establishes a precedent (separate-per-surface credentials) that keeps future privileged surfaces from defaulting to reusing the SSH password by inertia.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li>Whichever option is chosen adds real implementation surface (login flow, session or credential storage, reset path) that does not exist in the appliance today — nothing about this ADR is free.</li><li>A new credential is another thing a household can lose, forget, or reuse insecurely across services, the same usability cost every new credential carries.</li></ul><h3 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h3><ul><li>Building session/login infrastructure from scratch (Option C) risks subtle security bugs (session fixation, insufficient entropy, missing CSRF protection) if not built carefully — favor well-worn libraries or patterns over a bespoke scheme.</li><li>Choosing Option A for short-term convenience quietly re-couples SSH and Console access, undermining the separation this ADR otherwise recommends; if that trade is made deliberately it should be recorded as such, not accidental.</li><li>Whatever mechanism is chosen must be re-verified once Console actually starts calling <code>sovereign-update</code> subcommands — this ADR reasons about the auth boundary in the abstract but does not itself qualify the privilege-escalation path from an unprivileged Console backend to a root update action; that remains a separate, necessary design step even after this ADR is decided.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><h3 id="no-authentication-keep-console-read-only-indefinitely" tabindex="-1">No authentication; keep Console read-only indefinitely <a class="header-anchor" href="#no-authentication-keep-console-read-only-indefinitely" aria-label="Permalink to &quot;No authentication; keep Console read-only indefinitely&quot;">​</a></h3><p>Rejected as a long-term stance — it&#39;s exactly the state ADR-0005 already described as temporary (&quot;Authentication is required before settings, restarts, updates, credential changes... are added&quot;), and the ROADMAP already commits to Console-triggered update installation as a named milestone outcome. Deferring this ADR further only delays a decision the project has already signaled it needs to make.</p><h3 id="oauth-third-party-identity-provider" tabindex="-1">OAuth / third-party identity provider <a class="header-anchor" href="#oauth-third-party-identity-provider" aria-label="Permalink to &quot;OAuth / third-party identity provider&quot;">​</a></h3><p>Rejected outright as inconsistent with this project&#39;s stated self-sufficiency values (the same reasoning ADR-0006 applied to reject cloud KMS for signing-key custody) and wildly disproportionate for a single-household, single-admin appliance with no multi-tenant concept.</p><h2 id="validation-and-revisit-conditions" tabindex="-1">Validation and Revisit Conditions <a class="header-anchor" href="#validation-and-revisit-conditions" aria-label="Permalink to &quot;Validation and Revisit Conditions&quot;">​</a></h2><p>Revisit this ADR if: Console&#39;s privileged surface grows enough that a single flat credential feels insufficient (e.g. multiple household members needing different privilege levels, which would favor a small role concept this ADR does not attempt to design), the device is ever expected to be reachable beyond the LAN by design rather than by accident (which would favor Option D or at least mandatory rate-limiting/lockout hardening beyond what&#39;s recommended here), or implementation reveals that the chosen mechanism can&#39;t cleanly gate the privilege-escalation path into <code>sovereign-update</code> (which would need its own follow-up design work regardless of which auth option is chosen here).</p>',68)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
